```javascript
function sortJsonObjectByKeys(jsonObj) {
  // Convert JSON object to an array of key-value pairs
  const entries = Object.entries(jsonObj);

  // Sort the array based on keys using a custom compare function
  const sortedEntries = entries.sort((a, b) => {
    return a[0].localeCompare(b[0], undefined, { sensitivity: 'accent' });
  });

  // Convert the sorted array back into a JSON object
  return Object.fromEntries(sortedEntries);
}

// Example usage:
const myJsonObj = { "zebra": 123, "apple": 456, "carrot": 789 };
console.log(sortJsonObjectByKeys(myJsonObj));
// Output: { apple: 456, carrot: 789, zebra: 123 }
